head.script:
scwin.onpageload = function() {}
scwin.onpageunload = function() {}
scwin.trigger1_onclick = function() {
    layout1.addResizeBar(1, "row");
}
scwin.trigger2_onclick = function() {
    layout1.addResizeBar(1, "col", {
        "start": "2"
    });
}
scwin.simulateWrapper = function(target, type, options) {
	WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate = function() {
	scwin.simulateWrapper('#mf_mf_layout1_resizeBar_row_1', 'drag-n-drop', {
		dx: 0,
		dy: 300
	});
}
scwin.checkVal = function() {
    return WebSquare.wUnit.getJq('#wf_header').height() > 150;
}
scwin.unitTest = function() {
    //Init test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('mf_mf_layout1_resizeBar_row_1').click()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
    WebSquare.wUnit.addCommand("pause", "400");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop unit Test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
